double progress(Map p){final a=p['products'] as List? ?? [];if(a.isEmpty)return 0;return a.map<double>((x)=>(x['qty'] as num)==0?0:(x['done'] as num)/(x['qty'] as num)).fold(0,(a,b)=>a+b)/a.length;}
String day(dynamic d)=>d==null?'—':DateTime.parse(d.toString()).toString().substring(0,10);
Future<String> saveBytes(List<int> bytes,String name)async{final dir=await getApplicationDocumentsDirectory();final folder=Directory('${dir.path}/agencement_media');if(!await folder.exists())await folder.create(recursive:true);final safe='${DateTime.now().millisecondsSinceEpoch}_${name.replaceAll(RegExp(r'[^a-zA-Z0-9._-]'),'_')}';final f=File('${folder.path}/$safe');await f.writeAsBytes(bytes);return f.path;}
