 Future<void> excelReport(BuildContext c)async{final book=xl.Excel.createExcel();final sheet=book['Projets'];sheet.appendRow(['Projet','Client','Référence','Statut','Avancement']);for(final p in Store.I.projects){sheet.appendRow([p['name'],p['client'],p['reference'],p['status'],'${(progress(p)*100).toStringAsFixed(1)} %']);}final log=book['Production'];log.appendRow(['Projet','Produit','Opération','Équipe','Quantité','Date']);for(final e in Store.I.logs){log.appendRow([e['project'],e['product'],e['operation'],e['team'],e['qty'],day(e['date'])]);}final bytes=book.save();if(bytes==null)return;final path=await saveBytes(bytes,'rapport_agencement.xlsx');await Share.shareXFiles([XFile(path)]);}
 Widget build(BuildContext c)=>ListView(padding:const EdgeInsets.all(16),children:[const Text('Rapports et exports',style:TextStyle(fontSize:22,fontWeight:FontWeight.bold)),Text('${Store.I.projects.length} projets • ${Store.I.logs.length} saisies de production'),const SizedBox(height:12),FilledButton.icon(onPressed:()=>csv(c),icon:const Icon(Icons.table_chart),label:const Text('Exporter CSV')),const SizedBox(height:8),FilledButton.icon(onPressed:()=>pdfReport(c),icon:const Icon(Icons.picture_as_pdf),label:const Text('Exporter PDF')),const SizedBox(height:8),FilledButton.icon(onPressed:()=>excelReport(c),icon:const Icon(Icons.grid_on),label:const Text('Exporter Excel XLSX')),const SizedBox(height:18),const Text('Les fichiers sont générés localement puis partagés via le menu Android. Sauvegardez régulièrement vos données et médias : ils restent sur cet appareil.')]);}
